g=[[4]*13 for _ in range(20)]
marks=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
# original anchor markers
for r,c in marks:g[r][c]=1
# motif source
motif=[[4,5,5],[8,1,8],[8,5,0]]
for r,c in marks:
 for dr in range(-1,2):
  for dc in range(-1,2):
   v=motif[dr+1][dc+1]
   if v!=4:g[r+dr][c+dc]=v
# original seed motif
for r, row in [(11,[4,5,5]),(12,[8,5,8]),(13,[8,5,0])]:
 for dc,v in enumerate(row):
  if v!=4:g[r][6+dc]=v
print('\n'.join(' '.join(map(str,row)) for row in g))

